// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        // keep receiver a plain address that accepts transfers (not zero/precompiles)
        vm.assume(uint160(receiver) > 9);
        // only positive amounts are admissible (sending 0 wei is not a meaningful send)
        vm.assume(amount > 0);

        // fund the contract with exactly the amount so the transfer always succeeds
        vm.deal(address(c), amount);

        uint256 beforeReceiver = receiver.balance;
        uint256 beforeContract = address(c).balance;

        // owner is the test contract (deployer of c)
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        // the reference transfers exactly `amount` out and it lands in the receiver
        assertTrue(receiver.balance - beforeReceiver == amount &&
                    beforeContract - address(c).balance == amount);
    }
}
